// Method: Tree::scroll_to_item
static JSValue js_Tree_scroll_to_item(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "Tree.scroll_to_item: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "Tree.scroll_to_item: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    // Check WRITE rate limit (PRD Section 6.4)
    ExecutionLimiter* limiter = qjs_ctx->get_execution_limiter();
    if (limiter && !limiter->check_api_rate_limit(ApiCategory::WRITE)) {
        return JS_ThrowInternalError(ctx, "Tree.scroll_to_item: write rate limit exceeded");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "Tree.scroll_to_item: invalid or freed object");
    }

    Tree* typed_obj = Object::cast_to<Tree>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "Tree.scroll_to_item: object is not a Tree");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 2) {
        return JS_ThrowTypeError(ctx, "Tree.scroll_to_item: expected at least 1 arguments, got %d", argc - 1);
    }

    // Convert arguments
    TreeItem* arg_item = nullptr;
    if (JS_IsNumber(argv[1])) {
        // Direct handle (unwrapped by JS proxy)
        int64_t h_item; JS_ToInt64(ctx, &h_item, argv[1]);
        Object* obj_item = qjs_ctx->get_object_registry()->get_object(h_item);
        arg_item = reinterpret_cast<TreeItem*>(obj_item);
    } else {
        // Object with __handle property
        JSValue jh_item = JS_GetPropertyStr(ctx, argv[1], "__handle");
        if (!JS_IsUndefined(jh_item)) {
            int64_t h_item; JS_ToInt64(ctx, &h_item, jh_item);
            Object* obj_item = qjs_ctx->get_object_registry()->get_object(h_item);
            arg_item = reinterpret_cast<TreeItem*>(obj_item);
        }
        JS_FreeValue(ctx, jh_item);
    }
    // Optional argument: center_on_item (default: false)
    bool arg_center_on_item = false;
    if (argc > 2) {
        // Override default with provided value
        arg_center_on_item = JS_ToBool(ctx, argv[2]);
    }

    typed_obj->scroll_to_item(arg_item, arg_center_on_item);
    return JS_UNDEFINED;
}

